'*{box-sizing:border-box;margin:0;padding:0}
html,body{height:100%;overflow:hidden;background:transparent}

/* No overflow:hidden here. Combined with border-radius it forces a rounded clip,
   which makes the browser rasterise the whole card into one layer - and the page
   uses FitToWidth, so that layer then gets resampled and the text goes soft.
   body already has overflow:hidden, so nothing can spill regardless. */
.rr{height:100%;display:flex;flex-direction:column;
  font-family:''Segoe UI Variable Display'',''Segoe UI'',system-ui,sans-serif;
  background:#FFFFFF;border:1px solid #E3E8EF;border-radius:14px;
  box-shadow:0 3px 14px rgba(15,23,42,.06);padding:11px 16px 12px}

/* Sizes are px but the sibling cards'' titles are Power BI VCO titles in pt, so
   13pt/11pt must be written as 17.5px/13px to sit at the same optical weight. */
.hd{flex:0 0 auto;margin-bottom:8px}
.ht{font-size:17.5px;line-height:23px;font-weight:600;color:#111827}
.hs{font-size:13px;line-height:17px;color:#5B6672;
  white-space:nowrap;overflow:hidden;text-overflow:ellipsis}

/* This wrapper is the scrollbar fix and it does nothing else. Row heights were
   previously tuned by arithmetic against the visual''s declared 442px, which was
   wrong - the usable viewport is smaller than that, so the card overflowed and
   the HOST div scrolled, which body''s overflow:hidden cannot prevent because the
   host is outside this document. min-height:0 is required: a flex item defaults
   to min-height:auto and refuses to shrink below its content, so overflow:hidden
   alone would never engage. No border-radius here on purpose - a rounded clip is
   what rasterises a layer and softens text (see the .rr note above); a square
   clip does not. Rows are still sized to fit, so this should never actually
   clip - it is the guarantee, not the layout. */
.tw{flex:1 1 auto;min-height:0;overflow:hidden}

/* Natural height inside .tw, no flex:1 and no height:100% on the table itself.
   Those used to be here and were counter-productive: Chromium does not
   redistribute a stretched table box into its rows, so they bought nothing, while
   height:100% against a parent that overflowed helped push the card past the
   viewport. Row padding below is what fills the card; any leftover is dead space
   at the bottom of .tw, which is strictly better than a scrollbar. */
.t{width:100%;border-collapse:collapse;table-layout:fixed}
/* Schema takes the extra width so the Execution column starts further right and
   sits closer to Health, rather than stranded mid-table. */
.t th:nth-child(1),.t td:nth-child(1){width:17%}
.t th:nth-child(2),.t td:nth-child(2){width:14%}
.t th:nth-child(3),.t td:nth-child(3){width:32%}
.t th:nth-child(4),.t td:nth-child(4){width:16%}
/* Health took 3% off Schema when the detail line went to 13px: "1 failed &middot;
   17 skipped" is ~132px and 18% left only ~163px of usable width. Schema can
   afford it - it already wraps to two lines rather than needing the width. */
.t th:nth-child(5),.t td:nth-child(5){width:21%}

.t th{font-size:11px;line-height:14px;font-weight:600;letter-spacing:.07em;
  text-transform:uppercase;color:#5B6672;text-align:left;white-space:nowrap;
  padding:0 10px 7px;border-bottom:1px solid #E3E8EF}
.t th.h{text-align:right}
/* Left gutter guarantees separation from Schema even when Schema is truncated. */
.t th.ex,.t td.ex{padding-left:26px}

/* 9px, and deliberately conservative rather than derived to fill the card. The
   old 13px came from arithmetic that assumed 349px of usable tbody height and it
   overflowed in practice, so the budget is now set below what the numbers allow
   instead of at the limit. Tallest row is driven by the HEALTH cell, not Dbt run:
   pill 25 + 2 + detail 18 = 45, against Dbt run''s id 20 + sub 18 = 38. That puts
   the two detail rows at 45+18+1 = 64 and the three plain rows at 38+18+1 = 57,
   so 5 rows = 302. Any surplus shows as space under the last row, which is fine;
   .tw clips if this is still optimistic. */
.t td{padding:9px 10px;border-bottom:1px solid #F1F5F9;vertical-align:middle;overflow:hidden}
.t tbody tr:last-child td{border-bottom:0}
.t tbody tr{transition:background .18s ease;
  animation:rise .5s cubic-bezier(.22,.8,.28,1) backwards;
  animation-delay:calc(var(--i) * 55ms)}
.t tbody tr:hover{background:#F8FAFC}

.id{display:block;font-size:15px;line-height:20px;font-weight:600;color:#111827;
  font-family:''Cascadia Mono'',''Consolas'',ui-monospace,monospace}
/* Was 10.5px on #94A3B8 and unreadable. Bigger and materially darker - this is the
   run timestamp, not decoration. */
.sub{display:block;font-size:13px;line-height:18px;font-weight:500;color:#64748B;
  white-space:nowrap;overflow:hidden;text-overflow:ellipsis}

/* Chip and target stay on ONE line. Stacking the target under the chip would make
   this the tallest cell in the row and push five rows past the fixed 300px box. */
.cm{display:inline-block;font-size:12.5px;line-height:17px;font-weight:600;
  padding:3px 9px;border-radius:6px;white-space:nowrap}
.cm-build{color:#4338CA;background:#EEF2FF;border:1px solid #C7D2FE}
.cm-run{color:#1D4ED8;background:#EFF6FF;border:1px solid #BFDBFE}
.cm-test{color:#7C3AED;background:#F5F3FF;border:1px solid #DDD6FE}
.cm-seed{color:#0F766E;background:#F0FDFA;border:1px solid #99F6E4}
.cm-snap{color:#B45309;background:#FFFBEB;border:1px solid #FDE68A}
.cm-other{color:#475569;background:#F1F5F9;border:1px solid #E2E8F0}
.tg{font-size:12.5px;color:#64748B;margin-left:7px;white-space:nowrap}

/* Schema wraps to a SECOND line instead of truncating at one. Row height is set
   by the Dbt run cell (id 20 + sub 18 = 38px), so two 18px lines fit inside the
   existing row - the second line is free space that was already there.
   overflow-wrap:anywhere is required: schema names are underscore-delimited and
   CSS treats them as a single unbreakable word, so without it they would never
   wrap at all. It only breaks when needed, so a name that fits stays on one line.
   line-clamp:2 caps it at two lines and adds its own ellipsis beyond ~86 chars. */
.sc{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;
  overflow:hidden;overflow-wrap:anywhere;
  font-size:13px;line-height:18px;font-weight:500;color:#334155;
  font-family:''Cascadia Mono'',''Consolas'',ui-monospace,monospace}

/* Explicit line-height rather than the default: at 13.5px the normal line box is
   ~18.2px, and five of those plus the bar overflow the fixed 300px container. */
.ex .v{display:block;font-size:15.5px;line-height:21px;font-weight:600;color:#0F172A;
  font-variant-numeric:tabular-nums}
.ex .v small{font-size:11.5px;font-weight:500;color:#5B6672}
.ex .b{display:block;height:4px;max-width:130px;border-radius:2px;
  background:#EDF1F6;overflow:hidden;margin-top:5px}
.ex .b i{display:block;height:100%;border-radius:2px;background:#2563EB;
  animation:grow .75s cubic-bezier(.22,.8,.28,1) backwards;
  animation-delay:calc(var(--i) * 55ms + 110ms)}

.h{text-align:right}
.p{display:inline-flex;align-items:center;gap:6px;font-size:13px;font-weight:600;
  padding:3px 11px;border-radius:999px;white-space:nowrap}
.p i{width:7px;height:7px;border-radius:50%;background:currentColor}
.p.ok{color:#047857;background:#ECFDF5;border:1px solid #A7F3D0}
.p.no{color:#B91C1C;background:#FEF2F2;border:1px solid #FECACA}
/* Skipped-but-nothing-failed. Amber, not red: the DAG did not run, but nothing
   broke either, and folding it into Failed was what made the old single non-OK
   count read as eighteen breakages. */
.p.wa{color:#B45309;background:#FFFBEB;border:1px solid #FDE68A}
/* A STATIC ring, not the 1.8s infinite pulse this used to be. An animation with
   no end keeps its subtree permanently composited, so the health cell was the one
   part of the card the browser held as a cached bitmap - and the page is
   FitToWidth, so that bitmap got resampled instead of re-rendered at the page''s
   scale, which is what made the pill look soft while the rest stayed sharp (same
   rasterise-then-resample trap as the .rr note at the top). The entrance
   animations are safe because they finish and release the layer; this one never
   did. The ring reads as emphasis without costing a permanent layer. */
.p.no i{box-shadow:0 0 0 3px rgba(185,28,28,.14)}
/* Deliberately identical to .sub - 13px/18px, weight 500, #64748B - because this
   is the failed/skipped split, the number the reader actually came for, and it was
   previously set at 10px on #94A3B8 like a footnote. nowrap is load-bearing, not
   cosmetic: the row budget above assumes ONE 18px line, and a four-digit skip
   count wrapping would add 18px to two rows. td has overflow:hidden for that. */
.fx{display:block;font-size:13px;line-height:18px;font-weight:500;color:#64748B;
  margin-top:2px;font-variant-numeric:tabular-nums;white-space:nowrap}

.empty{margin:auto;font-size:13px;color:#94A3B8}

/* Entrance animates transform and the bar width only - never opacity. Power BI
   restarts CSS animations every time the page is shown, and animation-delay with
   fill-mode:backwards holds the FROM state for the length of the delay, so a
   faded-in row would leave the table blank for a moment on every visit. */
@keyframes rise{from{transform:translateY(8px)}}
@keyframes grow{from{width:0}}
@media (prefers-reduced-motion:reduce){
  .t tbody tr,.ex .b i{animation:none!important}
}'
